import{_ as i,o as u,c as n,a2 as t}from"./chunks/framework.CqpfiAoK.js";const l=JSON.parse('{"title":"Kanuni za Kuvuka Ndege","description":"","frontmatter":{},"headers":[],"relativePath":"sw/0081-位面穿梭规则.md","filePath":"sw/0081-位面穿梭规则.md"}'),k={name:"sw/0081-位面穿梭规则.md"};function e(h,a,o,d,w,s){return u(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="kanuni-za-kuvuka-ndege" tabindex="-1">Kanuni za Kuvuka Ndege <a class="header-anchor" href="#kanuni-za-kuvuka-ndege" aria-label="Permalink to &quot;Kanuni za Kuvuka Ndege&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>81</td></tr><tr><td>Moduli</td><td>Mwingiliano wa Kati ya Ndege na Kanuni za Wakati</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Kuvuka ndege, ruhusa ya kuvuka, kizingiti cha nishati, kizingiti cha nanga, kuzuia uchafuzi</td></tr></tbody></table><h2 id="_1-nafasi-ya-kisheria-ya-hatua-ya-kuvuka" tabindex="-1">1. Nafasi ya Kisheria ya Hatua ya Kuvuka <a class="header-anchor" href="#_1-nafasi-ya-kisheria-ya-hatua-ya-kuvuka" aria-label="Permalink to &quot;1. Nafasi ya Kisheria ya Hatua ya Kuvuka&quot;">​</a></h2><p>Kuvuka ndege inamaanisha hatua ya mtu au kundi la viumbe hai, kupitia njia za teknolojia au uwezo wa miungu, kuvuka kizuizi cha sheria kutoka ndege moja kuingia ndege nyingine. Chini ya muundo wa kisheria wa ustaarabu wa symbiosis wa nanga, kuvuka ndege kunagawanywa kama &quot;hatua maalum ya hatari ya juu&quot; na lazima iwe chini ya usimamizi mkali wa ruhusa na ufuatiliaji wa mchakato. Kifungu cha 47 cha &quot;Katiba ya Symbiosis&quot; kinabainisha waziwazi: &quot;Hakuna shirika au mtu anaweza kufanya kuvuka kati ya ndege bila ruhusa, wala kutumia kuvuka ndege kufanya shughuli za ukaji, kuingilia kazi au uchafuzi dhidi ya ustaarabu wa ndege nyingine.&quot;</p><p>Sababu ya msingi ya nini kuvuka ndege kinahitaji udhibiti mkali ni kwamba hatua yenyewe ya kuvuka inaweza kusababisha athari nyingi kwenye ndege lengwa: usumbufu wa sheria, sindano ya nishati, uchafuzi wa fahari, uvamizi wa vijidudu, na kuingilia kazi kitamaduni, kati ya mambo mengine. Athari hizi, kwa kiwango cha kidogo, husababisha hamsati za eneo kwenye ndege lengwa; kwa kiwango cha mkubwa, zinaweza kubadilisha njia ya mageuzi ya ustaarabu wake, hata kusababisha kuanguka kwa sheria. Kwa hivyo, lengo la msingi la kanuni za kuvuka ni &quot;kudhibiti athari ya nje ya hatua ya kuvuka ndani ya kizingiti cha kukubalika&quot;.</p><h2 id="_2-mfumo-wa-uainishaji-wa-ruhusa-ya-kuvuka" tabindex="-1">2. Mfumo wa Uainishaji wa Ruhusa ya Kuvuka <a class="header-anchor" href="#_2-mfumo-wa-uainishaji-wa-ruhusa-ya-kuvuka" aria-label="Permalink to &quot;2. Mfumo wa Uainishaji wa Ruhusa ya Kuvuka&quot;">​</a></h2><p>Hengyuanzhou inatekeleza mfumo wa uainishaji wa ruhusa ya kuvuka ndege, na kugawa ruhusa katika viwango vinne kulingana na lengo la kuvuka, aina ya ndege lengwa, na sifa ya mvukaji:</p><table tabindex="0"><thead><tr><th>Kiwango cha Ruhusa</th><th>Mazingira Yanayotumika</th><th>Shirika la Uidhinishaji</th><th>Muda wa Uhalali</th><th>Masharti ya Ziada</th></tr></thead><tbody><tr><td>Kiwango A (Uchunguzi wa Kichunguzi)</td><td>Uchunguzi wa kimasikio safi, hakuna mawasiliano yoyote ya kimwili</td><td>Ofisi ya Usimamizi wa Ndege</td><td>Kazi ya moja</td><td>Lazima kutumia mpango wa kioo cha nakala + nafasi iliyotengwa</td></tr><tr><td>Kiwango B (Ubadilishaji wa Kiakademia)</td><td>Ubadilishaji mdogo wa maarifa na ustaarabu wa ndege lengwa</td><td>Ofisi ya Usimamizi wa Ndege + Wizara ya Utamaduni</td><td>Mwaka mmoja zaidi</td><td>Lazima kusaini mkataba wa kutokuingilia kazi kwa pamoja</td></tr><tr><td>Kiwango C (Ushirikiano wa Rasilimali)</td><td>Ushirikiano wa rasilimali na teknolojia chini ya msingi wa usawa na faida ya pamoja</td><td>Uidhinishaji maalum wa Baraza la Nanga</td><td>Miaka mitatu zaidi</td><td>Lazima kupata ridhaa ya ustaarabu wa ndege lengwa</td></tr><tr><td>Kiwango D (Kuingilia Kazi kwa Dharura)</td><td>Kuingilia kazi kwa kibinadamu wakati ndege lengwa inakabiliwa na mzozo wa kiwango cha kutoweka</td><td>Uamuzi wa dharura wa Baraza la Nanga</td><td>Wakati wa mzozo</td><td>Lazima kuwasilisha ripoti kamili ya kuingilia kazi baadaye</td></tr></tbody></table><p>Ruhusa ya kuvuka ya kiwango chochote inakataza vitendo vifuatavyo: kunyang&#39;anya nishati ya asili ya ndege lengwa, kueneza kwa nguvu mtazamo wa ndege ya mwenyewe, kufanya mabadiliko ya jeni au fahari bila ridhaa, kuanzisha misingi ya kijeshi ya kudumu kwenye ndege lengwa, na aina yoyote ya utawala wa ukoloni.</p><h2 id="_3-mahitaji-ya-teknolojia-ya-kuvuka-na-kizingiti-cha-nishati" tabindex="-1">3. Mahitaji ya Teknolojia ya Kuvuka na Kizingiti cha Nishati <a class="header-anchor" href="#_3-mahitaji-ya-teknolojia-ya-kuvuka-na-kizingiti-cha-nishati" aria-label="Permalink to &quot;3. Mahitaji ya Teknolojia ya Kuvuka na Kizingiti cha Nishati&quot;">​</a></h2><p>Kuvuka ndege kinahitaji kutimiza masharti ya teknolojia ya mkali. Kwanza, mvukaji lazima awe na miungu ya hatua ya tatu (Hali ya Mabadiliko ya Nafasi) au zaidi ya &quot;mfumo wa usimamizi wa sheria ya nafasi&quot;, au abeba chombo cha kuvuka ndege kinachofuata viwango. Pili, nukta ya kuanza na ya mwisho ya kuvuka zote lazima ziwe na nanga kwa kizingiti cha koordinati; kuvuka kwa upasifu bila uupimaji wa nanga kunakatazwa kwa mkali.</p><p>Matumizi ya nishati wakati wa mchakato wa kuvuka yana sawa moja kwa moja na ukubwa wa kizuizi cha sheria cha ndege lengwa. Hengyuanzhou imeanzisha &quot;jedwali la kizingiti cha nishati ya kuvuka&quot; iliyofuata viwango, na nishati ya chini inayohitajika kwa kuvuka aina tofauti za ndege ni kama ifuatavyo:</p><ul><li>Ndege ya Msingi ya Vifaa: 1000 vitengo vya nishati vya kiwango</li><li>Ndege ya Udhihirisho wa Nishati: 5000 vitengo vya nishati vya kiwango</li><li>Ndege ya Fahari Inayoongoza: 20000 vitengo vya nishati vya kiwango</li><li>Ndege ya Sheria Iliyovunjika: 50000 vitengo vya nishati vya kiwango (na kiwango cha mafanikio chini ya 30%)</li><li>Ndege ya Karibu na Asili: thamani ya kinadharia zaidi ya 100000, kwa sasa hakuna rekodi za mafanikio</li></ul><p>Nishati ya kuvuka lazima ibebwe na mvukaji au chombo yenyewe, inakatazwa kuchimba nishati kutoka ndege lengwa kwa ajili ya mchakato wa kuvuka. Kanuni hii inalenga kuzuia hatua ya kuvuka kusababisha ukaji wa nishati kwenye ndege lengwa.</p><h2 id="_4-kuzuia-na-kudhibiti-uchafuzi-katika-mchakato-wa-kuvuka" tabindex="-1">4. Kuzuia na Kudhibiti Uchafuzi katika Mchakato wa Kuvuka <a class="header-anchor" href="#_4-kuzuia-na-kudhibiti-uchafuzi-katika-mchakato-wa-kuvuka" aria-label="Permalink to &quot;4. Kuzuia na Kudhibiti Uchafuzi katika Mchakato wa Kuvuka&quot;">​</a></h2><p>Moja ya hatari kubwa za kuvuka ndege ni &quot;uchafuzi wa kati ya ndege&quot;, ambayo inajumuisha uchafuzi wa kibaolojia (kubeba vijidudu vya ndege ya mwenyewe kuingia ndege lengwa), uchafuzi wa nishati (makosa ya nishati ya ndege ya mwenyewe yanayouingilia sheria za ndege lengwa), na uchafuzi wa fahari (mabadiliko ya fahari ya mvukaji yanaathiri eneo la fahari la ndege lengwa).</p><p>Ili kuzuia na kudhibiti uchafuzi, watuvaji wote lazima wakamilishe &quot;mpango wa usafi wa viwango vitatu&quot; kabla ya kuondoka:</p><ol><li><strong>Usafi wa kibaolojia</strong>: Kufanya uchunguzi na kuondoa vijidudu kwa masaa 72 katika nafasi iliyotengwa, kuhakikisha hawabebi pathojeni yoyote ya ndege ya mwenyewe</li><li><strong>Usafi wa nishati</strong>: Kubadilisha frequency ya nishati ya mvukaji hadi upeo unaofanana na ndege lengwa kupitia kifaa cha kizingiti cha nanga, kupunguza athari ya kukataa nishati</li><li><strong>Usafi wa fahari</strong>: Kufanya mafunzo ya kuzuia fahari, kuhakikisha wakati wa mchakato wa kuvuki hawatoa kwa hiari mabadiliko ya hiari ambayo yanaweza kuingilia eneo la fahari la ndege lengwa</li></ol><p>Zaidi ya hayo, upeo wa shughuli za mvukaji kwenye ndege lengwa umefadhiwa kwa mkali ndani ya &quot;eneo lililobainishwa na ruhusa ya kuvuka&quot;, kuenea bila ruhusa kunakatazwa. Baada ya kurudi ndege ya mwenyewe, mvukaji lazima apite tena uchunguzi wa kutengwa kwa muda usio chini ya siku 30 zilizobadilishwa kwa kasi ya mtiririko wa wakati wa ndege lengwa.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Kanuni za kuvuka ndege ni mstari wa kwanza wa ulinzi wa usalama wa mwingiliano wa kati ya ndege. Kupitia mifumo mitatu — uainishaji wa ruhusa, vikwazo vya teknolojia, na kuzuia uchafuzi — kuhakikisha kwamba hatua ya kuvuka daima inafanya kazi kwenye njia ya &quot;athari ndogo, inayoweza kufuatiliwa, inayoweza kuwajibika&quot;. Lengo la mwisho la kanuni sio kuzuia ubadilishaji kati ya ustaarabu, bali kufanya ubadilishaji ufanye kwa njia ya symbiosis, badala ya njia ya ukaji.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>80-Nadharia na Uainishaji wa Ndege</li><li>88-Miongozo ya Maadili ya Kati ya Ndege</li><li>62-Utekelezaji wa Teknolojia ya Sheria ya Nafasi</li></ul>',23)])])}const g=i(k,[["render",e]]);export{l as __pageData,g as default};
